    # - Unary code: reads bits until 0 is found
    # - Then reads 'bits' more bits in binary

    my $subtract_it = 1 << $bits;
    my $result_ans = $value + $subtract_it;

    # Find how many bits needed to represent result_ans
    my $bits_needed = $bits;
    while ((1 << $bits_needed) <= $result_ans) {
        $bits_needed++;
    }

    # Unary encoding: output (bits_needed - bits) ones, then a zero
    for (1..($bits_needed - $bits)) {
        put_bit(1);
    }
    put_bit(0);

    # Binary encoding: output bits_needed bits of result_ans (most significant first)
    for my $i (reverse 0..$bits_needed-1) {
        put_bit(($result_ans >> $i) & 1);
    }
