#!/usr/bin/perl
use strict;
use warnings;

# Reverse-engineer the arithmetic decoder to build proper encoder

# Read data
open(my $fh, '<', 'data.txt') or die "Cannot read data.txt";
my $data = do { local $/; <$fh> };
close($fh);

my $len = length($data);
print STDERR "Data length: $len bytes\n";

# First, build the bit sequence we want to encode
my @bits;

sub put_bit {
    my ($bit) = @_;
    push @bits, $bit ? 1 : 0;
}

sub encode_integer {
    my ($value, $bits) = @_;
    my $subtract_it = 1 << $bits;
    my $result_ans = $value + $subtract_it;

    my $bits_needed = $bits;
    while ((1 << $bits_needed) <= $result_ans) {
        $bits_needed++;
    }

    # Unary: (bits_needed - bits) ones, then zero
    for (1..($bits_needed - $bits)) {
        put_bit(1);
    }
    put_bit(0);

    # Binary: bits_needed bits
    for my $i (reverse 0..$bits_needed-1) {
        put_bit(($result_ans >> $i) & 1);
    }
}

# Simple compression: literals only
my @operations;
for my $i (0..$len-1) {
    my $byte = ord(substr($data, $i, 1));
    my $signed = $byte > 127 ? $byte - 256 : $byte;
    push @operations, [0, $signed];
}

print STDERR "Operations: ", scalar(@operations), "\n";

# Encode number of operations
encode_integer(scalar(@operations), 9);

# Encode each operation as literal
foreach my $op (@operations) {
    put_bit(0);  # literal flag
    my $sign = $op->[1] < 0 ? 1 : 0;
    put_bit($sign);
    my $mag = abs($op->[1]);
    encode_integer($mag, 4);
}

print STDERR "Total bits: ", scalar(@bits), "\n";

# Now implement the arithmetic encoder that mirrors the decoder
# The decoder tracks: range, fraction, and reads bytes via gc()
# We track: low, high, and output bytes

my @output_bytes;
my $range = 1;
my $fraction = 0;
my $radix = 255;
my %cc;  # Context counts: cc{ctx,0} and cc{ctx,1}

sub output_byte {
    my ($byte) = @_;
    push @output_bytes, $byte & 0xff;
}

sub encode_bit {
    my ($bit, $ctx) = @_;
    $ctx //= 0;

    # Ensure range is adequate
    while ($range < $radix) {
        $range *= $radix;
        $fraction *= $radix;
        # We need to output a byte that will be read as gc()
        # The decoder does: fraction += gc() - 1
        # So if we want to add value V to fraction, output V + 1

        # For now, output a neutral byte (128) which adds 127 to fraction
        output_byte(128);
        $fraction += 127;
    }

    # Get probability counts for this context
    my $c0 = $cc{"$ctx,0"} // 0;
    my $c1 = $cc{"$ctx,1"} // 0;

    # Calculate split point
    my $split = int($range * (1 + $c0) / ($c0 + $c1 + 2));

    # Update range and fraction based on bit
    if ($bit) {
        $fraction -= $split;
        $range -= $split;
        $cc{"$ctx,1"}++;
    } else {
        $range = $split;
        $cc{"$ctx,0"}++;
    }
}

# Encode all bits
for my $i (0..scalar(@bits)-1) {
    my $ctx = ($i < 20) ? 0 : ($i < 100) ? 1 : 9;  # vary context
    encode_bit($bits[$i], $ctx);
}

my $output = pack('C*', @output_bytes);
print STDERR "Encoded size: ", length($output), " bytes\n";

open(my $out, '>', 'data.comp') or die "Cannot write data.comp";
binmode($out);
print $out $output;
close($out);

